ctivities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","romance":"destination"},"commission_lane":["operator","package"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Ojos del Caburgua turquoise pools + falls","si_tag":"expedition","tier":"essential","source":"https://www.visitchile.com/en/ojos-del-caburgua/","timing":"[''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"[''Dec'', ''Jan'', ''Feb'']","commission":"half-day tour/transfer commissionable; site free/low-fee","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"}],"faq":null,"seo":{"meta_title":"Pucón, Chile Travel Guide — Villarrica Volcano, Hot Springs & Lake District Adventure | TravelWell","search_language":"es-CL","local_keywords":["qué hacer en Pucón","volcán Villarrica ascenso","Termas Geométricas","Parque Nacional Huerquehue","rafting río Trancura","termas cerca de Pucón","Ojos del Caburgua","experiencia mapuche ruka","cuándo ir a Pucón","Pucón es seguro"],"hreflang":["en","es-CL"],"jsonld_type":"TouristDestination","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/chile","read":"2026-08-20T14:47:39Z","source_updated":"2026-08-18T23:18:12+01:00"}]},"conten