  ('puerto-aventuras-mexico', '10S', 'Puerto Aventuras', 'Mexico', 'Gated marina, reef off the beach', 'live', 'verified', 'venice', 'Quintana Roo (Cancún & Riviera Maya)', '{"romance","diveglobal","ocean","wildlife"}', '{}', '{"comfort","premier"}', null, null, '{"key_facts":["One of the few mainland deep-water marinas between Cancún and Belize City — a safe-haven harbor.","The reef sits ~100 feet from shore, allowing several dives per day with minimal transit.","Gated community with controlled access and 24/7 security.","Adjacent Dolphin Discovery offers swims with dolphins, sea lions and manatees.","Cenote Azul (between Puerto Aventuras and Playa del Carmen) makes it an easy cenote-dive base."],"safety":{"emergency":"911","hospital":"Nearest trauma: Hospiten Riviera Maya, Playa del Carmen (+52 984 159 2200), ~20 km north; local clinics stabilize/transfer; major trauma to Cancún","malaria":"none in tourist Quintana Roo","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"MX","summary":"The FCDO advises against all but essential travel to named states, cities and border areas of Mexico — listed below in its own words, each with its own exceptions. The Yucatán Peninsula, Mexico City, Baja California Sur and the other main visitor regions carry no FCDO restriction.","source":"UK FCDO — Mexico travel advice, reviewed 2026-07-16 (verbatim snapshot from the research library)","_rule":"the FCDO restricted-area records for this country, verbatim. PRESENCE OF THIS BLOCK IS NOT A CLAIM THAT THIS DESTINATION SITS IN ANY OF THEM — membership is a coverage judgement and is set only in `zone_record`, by a human."}},"timing":{"peak":"Dec-Apr (dry season; highest rates, biggest crowds)","shoulder":"May-Jun & Nov (~30-40% off, good weather)","green":"Jun-mid-Oct (hurricane/low; cheapest; marina monitors weather)","marina_sportfishing_calendar":"charters year-round weather-permitting; peak billfish/dorado spring dry window (Mar-Jun sailfish/mahi); confirm species per season with operator","sargassum_window":"Apr-Aug (Jun-Jul peak); marina/inlet + dive focus softens beach dependence","fill_the_beds":"sargassum/green months lead with near-shore reef dives, Cenote Azul, Dolphin Discovery, sportfishing charters, marina promenade","fire_date":"peak campaigns open Aug-Sep; shoulder ~3-4 months out; spring-sportfishing / dive-base push through sargassum months","event_peaks":["Christmas/New Year","Spring Break (Mar)","Semana Santa"],"booking_lead":"peak 3-4 months (gated villa/condo stock finite, book earlier); shoulder 4-6 months"},"jewels":[{"name":"Deep-water marina sportfishing charter","si_tag":"Ocean Adventures","status":"future","tier":"premier","hook":"Half/full-day offshore charters from a rare mainland deep-water safe-haven harbor.","bookable_category":"fishing charter","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Half/full-day offshore charters from a rare mainland deep-water safe-haven harbor.","when":"Dec-Apr","commission":"affiliate 4-8% / DMC 12%; berth fees pass-through","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["ocean"],"shelf_fit":{"diveglobal":"destination","ocean":"primary","romance":"destination","wildlife":"destination"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Dolphin Discovery swim","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Sea-inlet swims with dolphins, sea lions and manatees beside the marina.","bookable_category":"marine wildlife experience","source":"https://www.dolphindiscovery.com/riviera-maya/riviera-maya.asp","si":"wildlife","blurb":"Sea-inlet swims with dolphins, sea lions and manatees beside the marina.","commission":"brand affiliate; park entry pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wildlife"],"shelf_fit":{"diveglobal":"destination","ocean":"destination","romance":"destination","wildlife":"primary"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Shore-adjacent reef dive (reef ~100 ft out)","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Near-shore reef dives with minimal transit — several dives in a day.","bookable_category":"reef dive","source":"https://www.prodiveinternational.com/diving/mexico/puerto-aventuras/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Near-shore reef dives with minimal transit — several dives in a day.","when":"Dec-Apr","commission":"dive-operator affiliate / DMC 12%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal"],"shelf_fit":{"diveglobal":"primary","ocean":"destination","romance":"destination","wildlife":"destination"},"commission_pct_low":12,"commission_pct_high":12,"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Cenote Azul cavern dive/snorkel","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Popular cenote between Puerto Aventuras and Playa — cave country from a marina base.","bookable_category":"cenote cavern dive (guide required)","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","si":"diveglobal","blurb":"Popular cenote between Puerto Aventuras and Playa — cave country from a marina base.","commission":"DMC 12% / affiliate 4-8%; entry pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal"],"shelf_fit":{"diveglobal":"primary","ocean":"destination","romance":"destination","wildlife":"destination"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Dreams Aventuras Riviera Maya","si_tag":"Romance & Honeymoons","status":"live","tier":"premier","hook":"Secure, calm gated-community all-inclusive honeymoon base.","bookable_category":"all-inclusive resort","source":"https://www.trivago.com/en-US/oar/resort-dreams-aventuras-riviera-maya-puerto-aventuras","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Secure, calm gated-community all-inclusive honeymoon base.","when":"Dec-Apr","commission":"all-inclusive AOR ~12%","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["romance"],"shelf_fit":{"diveglobal":"destination","ocean":"destination","romance":"primary","wildlife":"destination"},"commission_pct_low":12,"commission_pct_high":12,"commission_lane":[],"commission_embedded":false,"commission_basis":"band"}],"faq":[{"q":"What''s the real risk to plan for in Puerto Aventuras?","a":"Water, mosquitoes, hurricanes and sargassum — not crime. Drink bottled/purified water, use repellent for dengue (peak May–November, no malaria in tourist Quintana Roo), and note hurricane season runs June–November. Sargassum is heavy region-wide in 2026 (Apr–Aug), but the marina and dive focus soften the beach hit here.","source":"cdc.gov / deeparrival.com, 2026-07-04","si_tag":"safety"},{"q":"What is the marina and sportfishing like in Puerto Aventuras?","a":"It is one of the few mainland deep-water marinas between Cancún and Belize City — a secure safe-haven harbor for yachts, sailors and sportfishers. Offshore charters run year-round (weather permitting), with the peak billfish and mahi window in the Mar–Jun spring dry season; berth fees are pass-through and the guided charter is the commissionable wrapper.","source":"alohawanderers.com, 2026-07-04","si_tag":"ocean"},{"q":"Is Puerto Aventuras a good dive base?","a":"Yes — it is a genuine near-shore reef and cenote base. The reef is only ~100 feet from the beach, so you can log several dives a day with minimal boat transit, and Cenote Azul (between Puerto Aventuras and Playa del Carmen) puts cave country within easy reach. Best reef visibility runs Nov–May.","source":"prodiveinternational.com / alohawanderers.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Is Puerto Aventuras good for families?","a":"Very — it is built for calm, safe family days. The adjacent Dolphin Discovery center offers sea-inlet swims with bottlenose dolphins, sea lions and manatees; add the gated 24/7-security layout, a calm marina promenade and near-shore reef, and it suits families and multigenerational groups well.","source":"dolphindiscovery.com, 2026-07-04","si_tag":"family"},{"q":"Is Puerto Aventuras good for a honeymoon?","a":"Yes, for couples who want secure and quiet over party energy. The in-community options are the branded all-inclusive Dreams Aventuras and private gated marina/golf villas with chef and concierge; the wider luxury tier runs ~US$400–600+/night in March. For branded ultra, Mayakoba (Rosewood, Banyan Tree) is ~30–40 min north with an easy marina/dive day trip.","source":"machupicchu.org / trivago.com, 2026-07-04","si_tag":"romance"},{"q":"Can I do Maya ruins from Puerto Aventuras?","a":"Yes — Tulum and Cobá are easy guided day trips, alongside Akumal''s turtle bay ~10 min south. Amstar and other Riviera Maya DMCs run cenote, Tulum-ruins and Akumal-turtle excursions from Puerto Aventuras; entries are pass-through, with the guided excursion the commissionable wrapper.","source":"embracethejourneytravel.com, 2026-07-04","si_tag":"culture"},{"q":"When is the best time to visit Puerto Aventuras?","a":"December–April is peak (best weather, highest rates); the value windows are the May–June and November shoulders at ~30–40% off, with November clear of sargassum. The green season (Jun–mid-Oct) is hot, rainy and cheapest with hurricane exposure — but the marina and dive product hold up better than a pure beach stay.","source":"machupicchu.org / travelswithelle.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Puerto Aventuras Travel Guide 2026 — Marina, Reef Diving & Dolphins | TravelWell.World","meta_description":"Plan Puerto Aventuras: a gated deep-water marina town with reef 100 ft from shore, cenote diving, dolphin swims and sportfishing, plus 2026 sargassum, safety and dive-chamber info.","slug":"puerto-aventuras-mexico","jsonld_type":"TouristDestination","content_freshness":"2026-07-04","search_language":["en","es-MX"],"local_keywords":["qué hacer en Puerto Aventuras","marina Puerto Aventuras","buceo en Puerto Aventuras","Dolphin Discovery Puerto Aventuras","pesca deportiva Puerto Aventuras","villas en Puerto Aventuras","Cenote Azul Puerto Aventuras","es seguro Puerto Aventuras"],"hreflang":["en","es-MX"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Private gated marina/golf villas","price_tier":"luxury","virtuoso":false,"earning":"on application / host or luxury-DMC villa AOR","mor_posture":true,"note":"top of in-community ladder; no true ultra hotel in-community","source":"https://www.rentalescapes.com/rentals/luxury-vacation-rentals-mexico/riviera-maya/puerto-aventuras"},{"name":"Dreams Aventuras Riviera Maya","price_tier":"premier","virtuoso":false,"earning":"all-inclusive AOR ~12% (Hyatt Inclusive/host)","mor_posture":true,"note":"top hotel SKU in-community, not true ultra","source":"https://www.trivago.com/en-US/oar/resort-dreams-aventuras-riviera-maya-puerto-aventuras"},{"name":"Rosewood Mayakoba (~30-40 min north)","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"note":"nearest true ultra hotel","source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Banyan Tree / Andaz-Alila Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"La Casa de la Playa (Grupo Xcaret)","price_tier":"ultra","virtuoso":true,"earning":"15% via Xcaret Agents Pro OR host-Virtuoso ($100 credit)","mor_posture":true,"source":"https://www.virtuoso.com/hotels/16561922/la-casa-de-la-playa"}],"source_verified":"2026-07-04","hero":{"query":"Puerto Aventuras, Mexico"},"geo":{"lat":20.4986,"lng":-87.2261},"orbit":[{"id":"akumal-mexico","jewels":5,"si":["diveglobal","ocean","culture"]},{"id":"bacalar-mexico","jewels":6,"si":["tropical","wellness","adventure"]},{"id":"cancun-mexico","jewels":5,"si":["tropical","adventure","diveglobal","ocean"]},{"id":"coba-mexico","jewels":5,"si":["culture","expedition","family"]},{"id":"cozumel-mexico","jewels":5,"si":["diveglobal","liveaboard","ocean"]},{"id":"holbox-mexico","jewels":4,"si":["expedition","romance","ocean","wildlife"]},{"id":"isla-contoy-mexico","jewels":3,"si":["expedition","ocean","wildlife"]},{"id":"isla-mujeres-mexico","jewels":5,"si":["tropical","ocean","diveglobal","adventure"]},{"id":"mahahual-mexico","jewels":5,"si":["liveaboard","diveglobal"]},{"id":"playa-del-carmen-mexico","jewels":5,"si":["romance","expedition","diveglobal","culture"]},{"id":"puerto-morelos-mexico","jewels":5,"si":["diveglobal","ocean","adventure","culinary"]},{"id":"sian-kaan-mexico","jewels":5,"si":["expedition","wildlife","tropical"]},{"id":"tulum-mexico","jewels":5,"si":["expedition","diveglobal","culture","wildlife"]}],"orbit_country":["balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","costalegre-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","huatulco-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","puerto-vallarta-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sayulita-mexico","teotihuacan-mexico","tlaquepaque-mexico","todos-santos-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 83),
  ('puerto-morelos-mexico', '10S', 'Puerto Morelos', 'Mexico', 'A reef 500 meters off a sleepy fishing dock', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"diveglobal","ocean","adventure","culinary"}', '{}', '{"essential","comfort","premier"}', null, 'core', '{"key_facts":["Puerto Morelos Reef National Park lies less than 500 m offshore, one of the best-preserved in the Caribbean","Juan Escutia boat is now an artificial reef; reef holds turtles, rays, nurse/bull sharks","Northern gateway to the ~17 km Route of the Cenotes (entry ~150-250 MXN each)","Deep-sea fishing for dorado, wahoo, tuna, barracuda","Runs ~20-30% cheaper than Playa del Carmen, 40-60% cheaper than Cancún Hotel Zone"],"safety":{"emergency":"911","hospital":"town clinics; major trauma in Cancún (~36 km, Galenia/Hospiten - verify) or Playa del Carmen; hyperbaric via SSS Cancún / Cozumel","malaria":"none in QR tourist zones (verify); dengue precautions","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"MX","summary":"The FCDO advises against all but essential travel to named states, cities and border areas of Mexico — listed below in its own words, each with its own exceptions. The Yucatán Peninsula, Mexico City, Baja California Sur and the other main visitor regions carry no FCDO restriction.","source":"UK FCDO — Mexico travel advice, reviewed 2026-07-16 (verbatim snapshot from the research library)","_rule":"the FCDO restricted-area records for this country, verbatim. PRESENCE OF THIS BLOCK IS NOT A CLAIM THAT THIS DESTINATION SITS IN ANY OF THEM — membership is a coverage judgement and is set only in `zone_record`, by a human."}},"timing":{"peak":"Dec-Apr (dry/high season; driest reef water, own rates peak)","shoulder":"May-Jun & Nov (~30-40% off winter, layered on structural ~20-30% vs Playa del Carmen)","green":"Jun-mid-Oct (hurricane season, ~40-60% off; reef/cenote year-round, dry-season visibility best)","booking_lead":"shoulder/green beds 2-4 wks; reef/cenote tours 1-3 wks; Dec-Apr beds + Zoëtry/Royalton Reserve ultra suite 3-6+ months (more for Christmas/NY)","off_season_specials":"double-discount play - ''cheaper than Cancún AND low season''; pair value bed with year-round national-park reef + weather-resilient Route of the Cenotes; disclose hurricane/sargassum","event_peaks":"Christmas-New Year, US spring break (Mar); no single marquee wildlife event - reef + cenotes are the year-round draw","fire_date":"winter/value-vs-Cancún Aug-Sep; green-season ''cheaper base + cenotes'' Apr-May; ultra corridor (Mayakoba/Zoëtry) 6-9 months ahead"},"jewels":[{"name":"Juan Escutia wreck","si_tag":"diveglobal","status":"future","tier":"comfort","hook":"sunken boat now an artificial reef and fish refuge","bookable_category":"guided reef/wreck dive","source":"https://www.kooxdiving.com/en/activities/diving-in-the-sea/puerto-morelos-reef-shipwreck-diving/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"sunken boat now an artificial reef and fish refuge","when":"Dec-Apr","commission":"local dive-op → OTA affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","ocean"],"shelf_fit":{"adventure":"destination","culinary":"destination","diveglobal":"primary","ocean":"evidenced"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Puerto Morelos Reef National Park snorkel","si_tag":"ocean","status":"future","tier":"essential","hook":"living reef under 500 m offshore, turtles/rays/lobster","bookable_category":"guided reef snorkel/dive","source":"https://voyage-mexico.com/en/puerto-morelos.html","si":"ocean","blurb":"living reef under 500 m offshore, turtles/rays/lobster","commission":"local operator → OTA (park fee pass-through)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","ocean"],"shelf_fit":{"adventure":"destination","culinary":"destination","diveglobal":"evidenced","ocean":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Deep-sea fishing charter","si_tag":"ocean","status":"future","tier":"premier","hook":"half/full-day for dorado, wahoo, tuna, barracuda","bookable_category":"private/shared charter","source":"https://voyage-mexico.com/en/puerto-morelos.html","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"half/full-day for dorado, wahoo, tuna, barracuda","when":"Dec-Apr","commission":"local charter operator → curated-recommend","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["ocean"],"shelf_fit":{"adventure":"destination","culinary":"destination","diveglobal":"destination","ocean":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Route of the Cenotes","si_tag":"globaladv","status":"future","tier":"comfort","hook":"~17 km jungle road of open/semi-open/cave cenotes","bookable_category":"day tour + per-cenote entry","source":"https://snorkelingadventure.com/blog/snorkeling-puerto-morelos-cenotes-riviera-maya-adventure/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"~17 km jungle road of open/semi-open/cave cenotes","when":"Dec-Apr","commission":"DMC/local operator → OTA (entry pass-through)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure"],"shelf_fit":{"adventure":"primary","culinary":"destination","diveglobal":"destination","ocean":"destination"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Fishing-village seafood + craft market","si_tag":"culinary","status":"future","tier":"essential","hook":"fresh-off-the-boat ceviche + plaza craft market","bookable_category":"food/culture experience","source":"https://www.palladiumhotelgroup.com/en/travel-guides/mexico/riviera-maya/what-to-see/puerto-morelos","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"fresh-off-the-boat ceviche + plaza craft market","when":"Dec-Apr","commission":"curated-recommend (largely non-commissionable)","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary","ocean"],"shelf_fit":{"adventure":"destination","culinary":"primary","diveglobal":"destination","ocean":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"}],"faq":[{"q":"What''s the real risk to plan for in Puerto Morelos?","a":"Sargassum, hurricanes and water — not crime. 2026 is heavy region-wide for sargassum, and Puerto Morelos'' open Caribbean-facing beaches are affected, so plan cenote and reef days as hedges; drink bottled water, use repellent for dengue (no malaria in the tourist zone), and note hurricane season runs June–November, September riskiest.","source":"howisthesargassum.com","si_tag":"safety"},{"q":"Is Puerto Morelos good for diving and the Juan Escutia wreck?","a":"Yes — it is an underrated day-boat dive base. The Puerto Morelos Reef National Park sits under 500 m offshore, one of the Caribbean''s best-preserved reefs, and the sunken Juan Escutia is now an artificial reef and fish refuge steps away. Visibility is best in the dry Oct–March window; book in town, where it is cheaper and supports local operators.","source":"voyage-mexico.com","si_tag":"diveglobal"},{"q":"Can I go deep-sea fishing from Puerto Morelos?","a":"Yes — it is a working fishing port, so charters are authentic and close at hand. Half- and full-day trips target dorado (mahi-mahi), wahoo, tuna and barracuda, with gear and guide included; the species mix is seasonal, so confirm with the operator. It pairs naturally with the fresh-off-the-boat ceviche at the beachfront cantinas.","source":"voyage-mexico.com","si_tag":"ocean"},{"q":"What is the Route of the Cenotes?","a":"A ~17 km jungle road of cenotes running inland from town — Puerto Morelos is its northern gateway. It strings together open, semi-open and cave cenotes for swimming, cavern diving and ziplining, at roughly 150–250 MXN entry each. Because they are shaded jungle sites, cenotes are weather-resilient — a strong rainy-day and green-season option.","source":"snorkelingadventure.com","si_tag":"globaladv"}],"seo":{"meta_title":"Puerto Morelos, Mexico: Reef, Cenotes & Fishing Village","meta_description":"A quiet Riviera Maya port with a national-park reef 500 m offshore, the Juan Escutia wreck, and the Route of the Cenotes. Cheaper than Cancún — when and how to book.","slug":"puerto-morelos-mexico","primary_keyword":"Puerto Morelos reef diving","long_tail":["Puerto Morelos Reef National Park","Juan Escutia wreck dive","Route of the Cenotes Puerto Morelos","Puerto Morelos fishing village","Puerto Morelos vs Cancun value"],"search_language":"es-MX (restated, not machine-translated)","local_keywords":["arrecife Puerto Morelos","Parque Nacional Arrecife de Puerto Morelos","buceo pecio Juan Escutia","Ruta de los Cenotes","pueblo pesquero Puerto Morelos","villas frente al mar Puerto Morelos","qué hacer en Puerto Morelos"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"codes":[],"note":"MXN currency, USD widely accepted","advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-07-31","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"ocean","name":"ocean","status":"future"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"culinary","name":"culinary","status":"future"}],"ultra":[{"name":"Zoëtry / Royalton Reserve Paraíso de la Bonita, a Luxury Collection Resort, Riviera Maya","why_ultra":"IN Puerto Morelos (Hwy Km 328); 90-100 ocean-front suites w/ plunge pools, 14 acres, thalasso spa, one of only 3 Luxury Collection all-inclusives worldwide, AAA Five Diamond 15 yrs (Zoëtry heritage); rebranded to Royalton Reserve adults-only, operating 2026 - verify current brand","earning":"on application / via host-Virtuoso (Marriott Luxury Collection + Royalton/Blue Diamond); verify %","virtuoso_value_add":"verify Marriott STARS/Luxury Collection amenities - not documented","mor":"commission-on-net; no net-rate resale markup","source":"https://www.tripadvisor.com/Hotel_Review-g240327-d28213141-Reviews-Royalton_Reserve_Paraiso_de_la_Bonita_a_Luxury_Collection_Resort_Riviera_Maya_Adult_A.html"},{"name":"Mayakoba enclave (Rosewood / Banyan Tree / Fairmont / Andaz) - ADJACENT, verify municipality","why_ultra":"620-acre gated ultra enclave, 4 flagship resorts; STRAIGHT GEOGRAPHY: administratively in Solidaridad (Km 298, Playa del Carmen area), NOT Puerto Morelos - do not label as in Puerto Morelos; nearest true-ultra cluster + standard corridor pull-out","earning":"on application / via host-Virtuoso (Rosewood Elite / Fairmont / Hyatt Prive / Banyan Tree); verify %","virtuoso_value_add":"Rosewood Mayakoba is Virtuoso-preferred - verify current amenity package","mor":"commission-on-net; no resale markup","source":"https://w