  ('puerto-vallarta-mexico', '10S', 'Puerto Vallarta', 'Mexico', 'Humpback season on Banderas Bay', 'live', 'verified', 'tropicalBeach', 'Jalisco (Puerto Vallarta & Guadalajara)', '{"romance","expedition","ocean"}', '{}', '{"comfort","luxury"}', null, null, '{"key_facts":["Banderas Bay hosts ~500–700 humpback whales each winter; season ~Dec 8–Mar 23 (Source: mismaloyaxtreme.com, Accessed 2026-07-04)","Hotel Mousai is the only AAA Five-Diamond resort in Puerto Vallarta (Source: travellemming.com, Accessed 2026-07-04)","Conchas Chinas is PV''s premier villa enclave, the ''Beverly Hills of Puerto Vallarta'' (Source: casabayvillas.com, Accessed 2026-07-04)","Los Arcos National Park holds the deepest water in Banderas Bay for certified divers (Source: vallarta-adventures.com, Accessed 2026-07-04)","Served by PVR (Lic. Gustavo Díaz Ordaz Intl) with direct US/Canada/UK flights (Source: en.wikipedia.org, Accessed 2026-07-04)"],"safety":{"emergency":"911","hospital":"Hospital San Javier Marina (Level III, trauma-capable); Hospital CMQ (three 24/7 bilingual locations)","book_enabled":true,"air_access_verified":"PVR (Lic. Gustavo Díaz Ordaz Intl)","malaria":"none in resort zone; dengue seasonal (rainy Jul–Oct)","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"MX","summary":"The FCDO advises against all but essential travel to named states, cities and border areas of Mexico — listed below in its own words, each with its own exceptions. The Yucatán Peninsula, Mexico City, Baja California Sur and the other main visitor regions carry no FCDO restriction.","source":"UK FCDO — Mexico travel advice, reviewed 2026-07-16 (verbatim snapshot from the research library)","_rule":"the FCDO restricted-area records for this country, verbatim. PRESENCE OF THIS BLOCK IS NOT A CLAIM THAT THIS DESTINATION SITS IN ANY OF THEM — membership is a coverage judgement and is set only in `zone_record`, by a human."}},"timing":{"peak":"Nov–Apr (dry; overlaps humpback season Dec–Mar)","shoulder":"May–Jun, late Oct","green":"Jul–Oct (rainy/hurricane season)","booking_lead":"Dec–Mar villas 4–6+ months; shoulder 6–10 weeks","off_season_specials":"Jul–Oct value campaign: beaches + diving + villa-with-chef (no whales)","event_peaks":"US/Canada winter holidays (late Dec–early Jan); spring break (Mar)","fire_date":"Aug–Sep for whale/Romance (Dec–Mar arrivals); May–Jun for green-season value"},"jewels":[{"name":"Humpback panga at dawn, Banderas Bay","si_tag":"GEA","status":"live","hook":"~500–700 humpbacks breed within sight of shore Dec–Mar","bookable_category":"tour","tier":"comfort","source":"https://mismaloyaxtreme.com/en/whale-watching-puerto-vallarta-2025-2026-guide/ (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"~500–700 humpbacks breed within sight of shore Dec–Mar","when":"Nov–Apr","commission":"DMC/tour affiliate ~8–15%","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","ocean":"destination","romance":"destination"},"commission_pct_low":8,"commission_pct_high":15,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Los Arcos National Park dive","si_tag":"Ocean Adventures","status":"future","hook":"Deepest water in the bay — tunnels, rays, turtles","bookable_category":"tour","tier":"comfort","source":"https://www.vallarta-adventures.com/en/tour/scuba-los-arcos (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Deepest water in the bay — tunnels, rays, turtles","when":"Nov–Apr","commission":"tour affiliate ~8–12%","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean"],"shelf_fit":{"expedition":"destination","ocean":"primary","romance":"destination"},"commission_pct_low":8,"commission_pct_high":12,"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Marietas Islands","si_tag":"Ocean Adventures","status":"future","hook":"Pacific mantas + reef fish + Hidden Beach","bookable_category":"tour","tier":"comfort","source":"https://www.vallarta-adventures.com/en/tour/scuba-las-marietas-islands (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Pacific mantas + reef fish + Hidden Beach","when":"Nov–Apr","commission":"tour affiliate ~8–12%","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean"],"shelf_fit":{"expedition":"destination","ocean":"primary","romance":"destination"},"commission_pct_low":8,"commission_pct_high":12,"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Casa Kimberly","si_tag":"Romance & Honeymoons","status":"live","hook":"The Taylor/Burton love-story hotel, heart-shaped-tub suite","bookable_category":"hotel","tier":"luxury","source":"https://travellemming.com/hotels-in-puerto-vallarta/ (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"The Taylor/Burton love-story hotel, heart-shaped-tub suite","when":"Nov–Apr","commission":"hotel/host commission ~10%","accessed":"2026-07-04","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["romance"],"shelf_fit":{"expedition":"destination","ocean":"destination","romance":"primary"},"commission_pct_low":10,"commission_pct_high":10,"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Conchas Chinas villa with private chef","si_tag":"Romance & Honeymoons","status":"live","hook":"Hillside beachfront villa, chef/butler, minutes from Romantic Zone","bookable_category":"villa","tier":"luxury","source":"https://villaexperience.com/city/puerto-vallarta/ (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Hillside beachfront villa, chef/butler, minutes from Romantic Zone","when":"Nov–Apr","commission":"villa-agency commission via host (MoR ~10%)","accessed":"2026-07-04","wells":["stay","eat"],"wells_basis":"derived from name/blurb/hook","si_all":["romance"],"shelf_fit":{"expedition":"destination","ocean":"destination","romance":"primary"},"commission_pct_low":10,"commission_pct_high":10,"commission_lane":[],"commission_embedded":false,"commission_basis":"band"}],"faq":[{"q":"What''s the real risk to plan for?","a":"Staying in the tourist zone, not the interior. Fly into PVR (no need to transit the restricted interior), remain within PV / the Banderas Bay resort corridor, and don''t self-drive into the Jalisco interior. Health-wise, dengue is seasonal in the Jul–Oct rains — use repellent — and there is no malaria in the resort zone.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"When and how can I see the whales?","a":"On a licensed panga, roughly Dec 8–Mar 23, best in the morning. Around 500–700 humpbacks arrive in Banderas Bay each winter to breed and calve within sight of shore; whales are federally protected, so keep the regulated distance and do not swim with them. Morning departures mean calmer seas.","source":"mismaloyaxtreme.com, 2026-07-04","si_tag":"expedition"},{"q":"Is Puerto Vallarta good for a honeymoon, and where''s the top end?","a":"Yes — it''s a mature honeymoon and destination-wedding market. The in-city ultra rung is narrow but real: Hotel Mousai is PV''s only AAA Five-Diamond (145 suites + 4 penthouses), and the 9-room Casa Kimberly is the Taylor/Burton love-story hotel. Peak is Nov–Apr; hold marquee rooms and villas early.","source":"travellemming.com, 2026-07-04","si_tag":"romance"},{"q":"Can beginners dive Los Arcos?","a":"Los Arcos is a certified-diver site, not a beginner pool — it holds the deepest water in Banderas Bay, with tunnels, arches, rays and turtles. Dive within your certification, and observe the DAN no-fly interval of 18–24 hours before boarding a flight from PVR. Marietas Islands is the other certified-reef option.","source":"vallarta-adventures.com, 2026-07-04","si_tag":"ocean-adventures-—-future"},{"q":"Where are the best villas?","a":"Conchas Chinas and Amapas. PV''s \"Beverly Hills\" hillside enclave holds beachfront estates with private chef and butler just 5–10 minutes from the Romantic Zone; book Dec–Mar (the whale-and-holiday peak) 4–6+ months ahead. Route villas as agency/host merchant-of-record, never net-rate resale.","source":"casabayvillas.com / villaexperience.com, 2026-07-04","si_tag":"tropical"}],"seo":{"meta_title":"Puerto Vallarta Travel Guide 2026 — Whales, Villas & Banderas Bay | TravelWell.World","meta_description":"Plan Puerto Vallarta: humpback whale season (Dec–Mar), luxury villas in Conchas Chinas, Five-Diamond resorts, and diving Los Arcos — with the FCDO advisory explained and PV''s named carve-out.","long_tail":["Puerto Vallarta humpback whale season dates","Conchas Chinas villa rental with chef","diving Los Arcos Puerto Vallarta"],"search_language":"es-MX","local_keywords":["avistamiento de ballenas Puerto Vallarta","villas de lujo Conchas Chinas","Puerto Vallarta es seguro 2026","buceo Los Arcos Puerto Vallarta","hoteles todo incluido Puerto Vallarta"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]},"primary_keyword":["Puerto Vallarta travel","Puerto Vallarta whale watching","Puerto Vallarta luxury villas","is Puerto Vallarta safe 2026"]},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"expedition","status":"live"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Hotel Mousai","why_ultra":"Only AAA Five-Diamond resort in PV; hilltop suites + penthouses over Banderas Bay","earning":"on application / via host","virtuoso_value_add":"verify Virtuoso/preferred; if listed, breakfast + credit + upgrade","mor":"hotel"},{"name":"Garza Blanca Preserve Resort & Spa","why_ultra":"Private-beach sister to Mousai; shared facilities","earning":"on application / via host","virtuoso_value_add":"verify","mor":"hotel"},{"name":"Casa Kimberly","why_ultra":"9-room Taylor/Burton icon, bay-view Taylor suite","earning":"host/hotel commission on application","virtuoso_value_add":"verify","mor":"hotel"},{"name":"Conchas Chinas / Amapas luxury villas (e.g. Villa Amapas South)","why_ultra":"~7,000 sq ft beachfront estate, chef/butler","earning":"villa-agency commission via host, on application","virtuoso_value_add":"n/a (villa)","mor":"agency/host (never net-rate resale)"},{"name":"One&Only Mandarina [Nayarit — state-line flag]","why_ultra":"Ultra resort in neighboring Riviera Nayarit, inside PV safety carve-out","earning":"on application / via host-Virtuoso","virtuoso_value_add":"verify","mor":"hotel"}],"source_verified":"2026-07-04","hero":{"query":"Puerto Vallarta, Mexico"},"geo":{"lat":20.6534,"lng":-105.2253},"orbit":[{"id":"careyes-mexico","jewels":7,"si":["ultra","romance","ocean"]},{"id":"chapala-ajijic-mexico","jewels":6,"si":["wellness","culture"