insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('puerto-viejo-costa-rica', '10S', 'Puerto Viejo (Southern Caribbean)', 'Costa Rica', 'Costa Rica''s Southern Caribbean', 'live', 'verified', 'tropicalBeach', 'Costa Rica', '{"tropical","expedition","culture","wildlife","ocean"}', '{"tropical"}', '{"essential","comfort"}', null, null, '{"key_facts":["Puerto Viejo de Talamanca is Costa Rica''s Southern Caribbean counter-culture coast: Afro-Caribbean + Bribri, reggae-slow beach towns, distinct from the Pacific side.","The Caribbean coast INVERTS the national weather pattern - driest and calmest in Sep-Oct and Feb-Mar, exactly when the Pacific is ''green season'' - a counter-seasonal selling point.","Cahuita National Park protects both a coral reef (guided snorkel only, ~$20pp) and a coastal rainforest walk with sloths, monkeys, iguanas and coatis.","Salsa Brava is an expert-only shallow reef break over sharp coral; beginners surf the Playa Cocles beach break; Punta Uva and Manzanillo are the calm swimming beaches.","Access is international via SJO (San Jose), then a ~4-4.5 hr drive southeast via Limon - a real distance, not a short transfer."],"safety":{"emergency":"911","ambulance_alt":"128 (Red Cross)","hospital":"24-hr private clinic in Puerto Viejo + public clinic Hone Creek (~5km); nearest hospital Limon (~1hr); major trauma routes to San Jose","medical_evacuation":"AirMed/Global Rescue-type air ambulance toward San Jose/repatriation; ~US$50,000 often full straight","book_enabled":true,"l2_disclosure":true,"petty_crime":"opportunistic theft is main risk (phones/wallets/purses); don''t leave beach valuables unattended, avoid poorly lit streets alone at night, don''t resist a robbery","air_access_verified":"SJO (San Jose) -> ~4-4.5 hr drive via Limon to Puerto Viejo (distance flag)","riptide":"Caribbean riptide risk; Salsa Brava = expert-only reef break over sharp coral; swim at calmer beaches (Punta Uva, Manzanillo)","wildlife":"snake/wildlife on jungle & national-park trails - go guided, stay on trail, no-touch","dengue":"seasonal mosquito-borne risk, occasional outbreaks; repellent advised","malaria":"low/localized; negligible in beach-town zone; relevant only for deep-forest hikes","water":"generally potable in Costa Rica incl. most of this zone; sensitive travelers/remote lodges may prefer bottled - confirm at property","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-20T14:54:18Z","page_updated":"2026-05-19T11:42:25+01:00","source_country":"costa-rica","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"counter_seasonal_peak_1":"Sep-Oct (Caribbean INVERTS national pattern: driest/calmest, best Cahuita snorkel visibility, rates ~30% lower)","counter_seasonal_peak_2":"Feb-Mar (driest most-reliable beach weather; least rain in March ~175mm)","surf_curve":"Salsa Brava swell Dec-Mar (dry-season window)","green_wet_variance":"wettest in the between-season troughs (~May-Aug bracket + secondary Nov-Dec lift); sell insured/refundable, lead with wildlife+reef-between-fronts","events":"Limon Carnival every October (Limon city; soca/calypso/reggae; Puerto Viejo lodging hub) + local Puerto Viejo/Manzanillo calypso nights (confirm 2026 dates)","fill_the_beds":"wet troughs lead with Jaguar Rescue Center, Sloth Sanctuary, Bribri cacao tour, indoor culture + reef/beach between fronts","campaign_start_trigger":"Sep-Oct counter-seasonal push fires mid-late Aug 2026 (headline); Feb-Mar + Salsa Brava fires late-Dec 2025/early-Jan 2026; Limon-Carnival fires late-Aug/early-Sep 2026","fire_date":"2026-08-17","booking_lead":"Sep-Oct value 3-5 weeks; Feb-Mar dry peak 6-10 weeks; Limon-Carnival Oct lodging 4-8 weeks"},"jewels":[{"name":"Cahuita National Park - reef snorkel + coastal wildlife walk","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Guided coral-reef snorkel PLUS a rainforest walk with sloths, monkeys, iguanas and coatis - reef + rainforest in one park.","bookable_category":"guided snorkel + wildlife hike","source":"https://mytanfeet.com/costa-rica-national-park/cahuita-national-park-costa-rica/","si":"expedition","blurb":"Guided coral-reef snorkel PLUS a rainforest walk with sloths, monkeys, iguanas and coatis - reef + rainforest in one park.","commission":"local-operator direct / affiliate 4-8%; park entry ($5 Puerto Vargas) + guide fee (~$20pp) pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","tropical","wildlife"],"shelf_fit":{"culture":"destination","expedition":"primary","ocean":"destination","tropical":"evidenced","wildlife":"evidenced"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["operator","affiliate","guide"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Punta Uva + Playa Cocles + Punta Cocles beach corridor","si_tag":"Tropical Islands / Beaches","status":"live","tier":"essential","hook":"Ivory-sand corridor - Punta Uva the calm swim/snorkel jewel, Cocles the beginner surf beach.","bookable_category":"self-guided beach","source":"https://mytanfeet.com/costa-rica-beach-information/punta-uva-puerto-viejo/","si":"tropical","blurb":"Ivory-sand corridor - Punta Uva the calm swim/snorkel jewel, Cocles the beginner surf beach.","commission":"none direct (drives lodging + F&B + kayak/surf attach)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["Tropical Islands / Beaches","ocean","tropical"],"shelf_fit":{"Tropical Islands / Beaches":"evidenced","culture":"destination","expedition":"destination","ocean":"evidenced","tropical":"primary","wildlife":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Tropical Islands / Beaches","si_map_basis":"normalised from free text ''Tropical Islands / Beaches'' by gen_normalise_jewel_si"},{"name":"Manzanillo / Gandoca-Manzanillo Wildlife Refuge","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"23,348-acre refuge from Punta Uva to Panama; 500+ ha protected reef, year-round dolphins, turtles, manatees, Manzanillo->Punta Mona coastal trail.","bookable_category":"guided snorkel/dolphin-watch + coastal hike","source":"https://costarica.org/beaches/caribbean/manzanillo/","si":"wildlife","blurb":"23,348-acre refuge from Punta Uva to Panama; 500+ ha protected reef, year-round dolphins, turtles, manatees, Manzanillo->Punta Mona coastal trail.","commission":"local-operator direct / affiliate; refuge entry pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical","wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","ocean":"destination","tropical":"evidenced","wildlife":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Jaguar Rescue Center","si_tag":"Wildlife & Nature","status":"future","tier":"essential","hook":"Rehab center for Caribbean wildlife - monkeys, sloths, kinkajous, toucans, macaws, snakes; guided tours.","bookable_category":"scheduled guided tour","source":"https://mylatinlife.com/puerto-viejo-talamanca-costa-rica-travel-guide/","si":"wildlife","blurb":"Rehab center for Caribbean wildlife - monkeys, sloths, kinkajous, toucans, macaws, snakes; guided tours.","commission":"affiliate / operator direct; admission largely pass-through/donation","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","ocean":"destination","tropical":"destination","wildlife":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Sloth Sanctuary (Cahuita)","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Sloth rescue + canoe wildlife-viewing tour near Cahuita.","bookable_category":"guided sanctuary + canoe tour","source":"https://mylatinlife.com/puerto-viejo-talamanca-costa-rica-travel-guide/","si":"wildlife","blurb":"Sloth rescue + canoe wildlife-viewing tour near Cahuita.","commission":"affiliate / operator direct; admission pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","ocean":"destination","tropical":"destination","wildlife":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Bribri indigenous territory + cacao/chocolate tour","si_tag":"Culture & Heritage","status":"future","tier":"comfort","hook":"Living-Indigenous immersion in the Talamanca foothills - walk the cacao agroforest, ferment/roast/grind, medicinal plants, home-cooked meal, waterfall.","bookable_category":"community cultural tour","source":"https://williestourscostarica.com/tours-old/bribri-indigenous-village-chocolate-tour-medicinal-plants/","si":"culture","blurb":"Living-Indigenous immersion in the Talamanca foothills - walk the cacao agroforest, ferment/roast/grind, medicinal plants, home-cooked meal, waterfall.","commission":"community-operator direct / affiliate; community fee pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","ocean":"destination","tropical":"destination","wildlife":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Salsa Brava reef break (watch or expert-only surf)","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"One of Central America''s heaviest waves over shallow coral - a spectator draw, an expert-only ride Dec-Mar; beginners to Cocles.","bookable_category":"expert self-guided / beginner-beach coaching","source":"https://www.kimkim.com/e/surf-lessons-at-salsa-brava-in-puerto-viejo-de-talamanca","si":"expedition","blurb":"One of Central America''s heaviest waves over shallow coral - a spectator draw, an expert-only ride Dec-Mar; beginners to Cocles.","commission":"affiliate on beginner surf lessons/rentals; watching free (F&B attach)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","ocean","tropical"],"shelf_fit":{"culture":"destination","expedition":"primary","ocean":"evidenced","tropical":"evidenced","wildlife":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Punta Uva clear-kayak (jungle river + emerald coast)","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"Clear kayaks up the jungle river/coast spotting toucans, monkeys, iguanas, river turtles.","bookable_category":"guided clear-kayak","source":"https://caribesurcr.com/tour-item/clear-kayak-tour/","si":"ocean","blurb":"Clear kayaks up the jungle river/coast spotting toucans, monkeys, iguanas, river turtles.","commission":"affiliate / operator direct","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean","wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","ocean":"primary","tropical":"destination","wildlife":"evidenced"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Afro-Caribbean cuisine (rondon + rice-and-beans in coconut)","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"The coast''s Creole table - rondon coconut-milk stew, rice-and-beans in coconut, calypso-culture kitchens.","bookable_category":"self-guided + food/culture tours","source":"https://soullifetravel.net/bribri-chocolate-indigenous-culture-costa-rica/","si":"culture","blurb":"The coast''s Creole table - rondon coconut-milk stew, rice-and-beans in coconut, calypso-culture kitchens.","commission":"affiliate on food tours; otherwise F&B attach","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","ocean":"destination","tropical":"destination","wildlife":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Limon Carnival (October) + calypso nights","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"The coast''s flagship Afro-Caribbean festival (soca/calypso/reggae/parades) in Limon each October; Puerto Viejo lodging hub.","bookable_category":"self-guided + festival-week lodging","source":"https://www.takeyourbackpack.com/backpacking-in-costa-rica/visit-limon-carnival/","si":"culture","blurb":"The coast''s flagship Afro-Caribbean festival (soca/calypso/reggae/parades) in Limon each October; Puerto Viejo lodging hub.","commission":"lodging AOR + affiliate on festival transfers","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","ocean":"destination","tropical":"destination","wildlife":"destination"},"commission_lane":["affiliate","event"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"Do you need a guide to snorkel Cahuita National Park?","a":"Yes — Cahuita''s reef snorkel is guided-only (~US$20 pp); you can''t bring your own gear and go solo, single-use plastics are banned, and no-touch coral discipline applies. Book the guided boat snorkel for best visibility Mar–Apr and Aug–Oct.","source":"mytanfeet.com, 2026-07-06","si_tag":"expedition"},{"q":"Is Puerto Viejo good for a honeymoon?","a":"Yes, as barefoot-luxury rather than palace-luxury. The ceiling is premier-to-luxury boutique — Le Cameleon (SLH) from ~US$186/night, or the 7-bungalow Tierra de Sueños wellness hideaway in Playa Chiquita — jungle-beach seclusion, adults-leaning, no marble required.","source":"lecameleonhotel.com, 2026-07-06","si_tag":"romance"},{"q":"When is Limón Carnival, and can you base in Puerto Viejo for it?","a":"Yes. Limón Carnival runs every October (started 1949) in the port city of Limón — soca, calypso, reggae and parades — with Puerto Viejo a common lodging hub a short hop south; confirm exact 2026 dates on live tracking.","source":"takeyourbackpack.com, 2026-07-06","si_tag":"culture"},{"q":"Can you see sloths and dolphins around Puerto Viejo?","a":"Easily. The town is ringed by jungle, so sloths, monkeys and colorful birds show right off the coast road, and the 23,348-acre Gandoca-Manzanillo refuge holds year-round bottlenose and tucuxi dolphins plus four sea-turtle species (Mar–Jul).","source":"costarica.org, 2026-07-06","si_tag":"wildlife"},{"q":"Can beginners surf Salsa Brava?","a":"No. Salsa Brava is an expert-only, powerful, shallow reef break over sharp coral — one of Central America''s heaviest waves — and it injures those who fall. Beginners and intermediates belong at the Playa Cocles beach break or a gentler beach; distinguish clearly at point of sale.","source":"kimkim.com, 2026-07-06","si_tag":"safety"},{"q":"How far is medical care if something goes wrong?","a":"A 24-hour private clinic in Puerto Viejo handles emergencies, with a public clinic in Hone Creek (~5 km) and the nearest large hospital in Limón (~1 hr); major trauma routes to San José. Air-evac cases can run ~US$50,000, often full straight — carry robust travel + air-evac insurance.","source":"puntauvarealty.com, 2026-07-06 · remax-oceansurf-cr.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Puerto Viejo de Talamanca, Costa Rica Travel Guide 2026 - Southern Caribbean, Sloths, Salsa Brava & Cahuita | TravelWell.World","meta_description":"Plan Costa Rica''s Southern Caribbean: Puerto Viejo de Talamanca, Cahuita reef & wildlife, Punta Uva & Manzanillo beaches, Salsa Brava surf, Bribri chocolate, boutique jungle-beach lodges, clear safety guidance, and the counter-seasonal Sep-Oct sweet spot.","slug":"puerto-viejo-costa-rica","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":"es-CR","local_keywords":["Puerto Viejo de Talamanca","Cahuita parque nacional","playas Caribe Sur Costa Rica","Punta Uva Costa Rica","refugio Gandoca-Manzanillo","tour de cacao Bribri","surf Salsa Brava","perezosos Puerto Viejo","Carnaval de Limon"],"hreflang":["en","es-CR"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-20T14:54:18Z","source_updated":"2026-05-19T11:42:25+01:00"}]},"primary_keyword":["Puerto Viejo Costa Rica travel guide","Southern Caribbean Costa Rica","Cahuita National Park snorkeling"]},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"expedition","status":"live"},{"si":"culture","status":"future"},{"si":"wildlife","status":"future"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Le Cameleon Boutique Hotel","price_tier":"luxury","virtuoso":false,"slh_member":true,"earning":"on application / host-Virtuoso / SLH trade / Fora","mor_posture":true,"note":"Playa Cocles beachfront; Small Luxury Hotels of the World; 51 rooms + 7 suites + 3 villas; the coast''s ceiling","source":"https://www.lecameleonhotel.com/"},{"name":"Tierra de Suenos Lodge & Wellness Center","price_tier":"premier-luxury","virtuoso":false,"earning":"host-agency AOR / Fora","mor_posture":true,"note":"7 hardwood Caribbean bungalows, Playa Chiquita; wellness/yoga hideaway","source":"https://tierradesuenoslodge.com/"},{"name":"Namuwoki Lodge","price_tier":"premier","virtuoso":false,"earning":"host-agency AOR / Fora","mor_posture":true,"note":"17 bungalows/villas, Playa Chiquita (Bribri ''Home of the Jaguar''); spa + restaurant","source":"https://www.namuwoki.com/"},{"name":"Physis Caribbean Bed & Breakfast","price_tier":"comfort-premier","virtuoso":false,"earning":"host-agency AOR / direct / Fora","mor_posture":true,"note":"intimate 4-room owner-run luxury B&B, Cocles","source":"https://physiscaribbean.net/about/"}],"source_verified":"2026-07-06","hero":{"query":"Puerto Viejo (Southern Caribbean), Costa Rica"},"geo":{"lat":9.6558,"lng":-82.7549},"orbit":[{"id":"guanacaste-costa-rica","jewels":10,"si":["tropical","expedition","liveaboard","wellness","wildlife"]},{"id":"la-fortuna-arenal-costa-rica","jewels":10,"si":["expedition","romance","wellness"]},{"id":"manuel-antonio-costa-rica","jewels":9,"si":["tropical","expedition","wildlife"]},{"id":"monteverde-costa-rica","jewels":12,"si":["expedition","wildlife","romance"]},{"id":"nosara-costa-rica","jewels":10,"si":["tropical","expedition","wellness"]},{"id":"osa-peninsula-corcovado-costa-rica","jewels":9,"si":["expedition","diveglobal"]},{"id":"san-jose-costa-rica","jewels":13,"si":["culture","expedition"]},{"id":"tortuguero-costa-rica","jewels":6,"si":["expedition","river"]}],"orbit_country":[]}'::jsonb, 86),
