"name":"Lake Coatepeque (volcanic caldera lake)","si_tag":"expedition","tier":"comfort","source":"https://www.booking.com/city/sv/coatepeque.html | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Dry season Nov–Apr","commission":"Lakeside boutique-hotel bookings (Cardedeu/Equinoccio) + boat excursions via operator","accessed":"2026-07-07","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["operator","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Apaneca Laguna Verde + Enganches/Ausol canopy zipline","si_tag":"expedition","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Crater lake ~5 km from Apaneca plus Central America''s longest cloud-forest ziplines","si":"expedition","blurb":"Crater lake ~5 km from Apaneca plus Central America''s longest cloud-forest ziplines","when":"Dry season Nov–Apr","commission":"DMC/operator activity affiliate","accessed":"2026-07-07","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Los Chorros de la Calera / Siete Cascadas waterfall hike (Juayúa)","si_tag":"expedition","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Terraced falls with cliff jumps and rappels. The 7 Waterfalls hike requires a mandatory guide — flash-flood, slick-rock, and cliff-jump hazards make guided mandatory","si":"expedition","blurb":"Terraced falls with cliff jumps and rappels. The 7 Waterfalls hike requires a mandatory guide — flash-flood, slick-rock, and cliff-jump hazards make guided mandatory","when":"Dry season Nov–Apr","commission":"Local guide via DMC; commissionable through operator (guided-only)","accessed":"2026-07-07","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["operator","DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Concepción de Ataco street art + coffee","si_tag":"culture","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"El Salvador''s most photogenic mural town — indigenous-history murals, Mirador de la Cruz, indigo-dye workshops, weekend street festival","si":"culture","blurb":"El Salvador''s most photogenic mural town — indigenous-history murals, Mirador de la Cruz, indigo-dye workshops, weekend street festival","when":"Dry season Nov–Apr","commission":"Mural-walk + coffee-finca combo via DMC; workshop fees via operator","accessed":"2026-07-07","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Nahuizalco Mercado Nocturno (night market)","si_tag":"culture","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"One of the few places you''ll see women in traditional Pipil dress; wicker-craft workshops and a rare evening artisan market","si":"culture","blurb":"One of the few places you''ll see women in traditional Pipil dress; wicker-craft workshops and a rare evening artisan market","when":"Dry season Nov–Apr","commission":"Evening add-on to route itinerary; craft purchases direct","accessed":"2026-07-07","wells":["stay","activities","shop"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary","culture"],"shelf_fit":{"culinary":"evidenced","culture":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Joya de Cerén — Pompeii of the Americas (UNESCO)","si_tag":"culture","tier":"essential","source":"https://www.viator.com/San-Salvador-attractions/Joya-de-Ceren-Archaeological-Site/d5585-a15755 | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"A 7th-century Maya farming village buried and preserved by volcanic ash; El Salvador''s only UNESCO World Heritage site. Open 9–4, closed Mondays; on-site museum","si":"culture","blurb":"A 7th-century Maya farming village buried and preserved by volcanic ash; El Salvador''s only UNESCO World Heritage site. Open 9–4, closed Mondays; on-site museum","when":"Dry season Nov–Apr","commission":"Guided heritage day trip via DMC/Viator; site entry non-commissionable","accessed":"2026-07-07","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Tazumal ruins (Chalchuapa)","si_tag":"culture","tier":"essential","source":"https://andysworldjourneys.com/2025/10/16/joya-de-ceren-and-tazumal-ancient-history-in-el-salvador/ | Accessed 2026-07-07","timing":"year-round","timing_type":"ALWAYS-ON","hook":"El Salvador''s most important pyramids/ceremonial platforms, ~40 min from Joya de Cerén — the two pair into one Maya-heritage day","si":"culture","blurb":"El Salvador''s most important pyramids/ceremonial platforms, ~40 min from Joya de Cerén — the two pair into one Maya-heritage day","when":"year-round","commission":"Combined Maya-heritage day trip w/ Joya de Cerén via DMC/operator; entry non-commissionable","accessed":"2026-07-07","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What is the Juayúa food festival?","a":"The Feria Gastronómica is the route''s flagship weekend market: every Saturday and Sunday, 11am–5pm, free entry, cash only, with the plaza filling with grills and pots — grilled meats $6–9, seafood ~$7, soups $3–4, pupusas ~$0.60, and roughly $10–20 feeds one person across multiple dishes. *[Culinary]*","source":"visitelsalvador.ai, Accessed 2026-07-07","si_tag":"culinary"},{"q":"Is Joya de Cerén worth visiting?","a":"Yes — it is El Salvador''s only UNESCO World Heritage site, a 7th-century Maya farming village buried and preserved by volcanic ash, earning the name \"Pompeii of the Americas.\" Open 9–4 and closed Mondays with an on-site museum, it pairs with the Tazumal ruins (~$5 entry, ~40 min away) into one Maya-heritage day. *[Culture & Heritage]*","source":"viator.com + andysworldjourneys.com, Accessed 2026-07-07","si_tag":"culture"},{"q":"Is the Santa Ana volcano hike dangerous?","a":"It is managed, not casual. Santa Ana (Volcán Ilamatepec, 2,381 m) is an active, monitored volcano with a turquoise sulphur crater lake and volcanic gas near the rim; the ~4–5 hour summit hike is guided-only, at scheduled departure times, and is subject to closure on activity alerts. Do not attempt it unguided, and confirm open status before booking.","source":"sallysees.com, Accessed 2026-07-07","si_tag":"safety"},{"q":"What outdoor adventures are on the Ruta de las Flores?","a":"The GEA spine runs from Santa Ana''s turquoise crater and Cerro Verde to Lake Coatepeque (a volcanic caldera lake beneath the volcano), plus Apaneca''s cloud-forest canopy ziplines (Los Enganches ~420 m lines) and the Laguna Verde crater lake ~5 km from Apaneca. Waterfall hikes at Los Chorros / Siete Cascadas round it out. *[GEA]*","source":"visitelsalvador.ai + sallysees.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Where do couples stay on the Ruta de las Flores?","a":"Two romance bookends: coffee-finca boutique on the route itself — Hotel Santa Leticia, a 19-room working-estate lodge from ~USD 78/night — or lakeside luxe on Lake Coatepeque, where Cardedeu Residence is a 5-star hotel and Equinoccio a boutique lakeside stay with balcony rooms over the water. There is no international five-star flag on the route. *[Romance]*","source":"lastfrontiers.com + booking.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What''s the real risk to plan for?","a":"Guided-only adventure and mountain roads. The Siete Cascadas 7-waterfall hike (~6 hrs) requires a mandatory guide (~$15/person) because of flash-flood, slick-rock, and cliff-jump hazards; canopy ziplines are operator-run with harness and briefing. The route itself is a cobblestone-and-switchback mountain drive — go in daylight, watch for highland fog, and prefer a local driver at night.","source":"visitelsalvador.ai, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Ruta de las Flores, El Salvador — Coffee Towns, Santa Ana Volcano & the Flower Route | TravelWell.World","jsonld_type":"TouristDestination","search_language":"es-SV","local_keywords":["Ruta de las Flores El Salvador","Volcán Santa Ana","Juayúa festival gastronómico","Concepción de Ataco murales","Laguna Verde Apaneca","tour de café Ruta de las Flores","Lago de Coatepeque hotel","Joya de Cerén Pompeya de América"],"hreflang":["en","es-SV"],"primary_keyword":"Ruta de las Flores","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/el-salvador","read":"2026-08-20T14:53:55Z","source_updated":"2026-06-17T14:04:09+01:00"}]},"content_freshness":"2026-07-07"},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"culture","status":"live"},{"si":"culinary","status":"live"}],"ultra":[{"property":"Hotel & Restaurante Santa Leticia (Apaneca)","note":"Boutique coffee-finca ceiling on the route itself; 19 rooms, on-farm coffee program","earning":"hotel commission via consortia/bedbank","mor":"hotel/OTA","tier":"$$–$$$"},{"property":"Cardedeu (5-star) / Equinoccio + private villas, Lake Coatepeque","note":"Caldera-lake luxe bookend under Santa Ana","earning":"hotel commission (Cardedeu/Equinoccio); villas referral/affiliate only","mor":"hotel for flags; Airbnb/VRBO for villas","tier":"$$$–$$$$"},{"property":"San Salvador city 5-star bookend","note":"Arrival/departure luxe anchor; where international-flag commission lives (verify availability)","earning":"hotel commission via preferred/Virtuoso program","mor":"hotel","tier":"$$$–$$$$"}],"source_verified":null,"hero":{"query":"Ruta de las Flores, El Salvador, El Salvador"},"geo":{"lat":13.8722,"lng":-89.7928},"orbit":[{"id":"suchitoto-el-salvador","jewels":10,"si":["romance","expedition","culture"]}],"orbit_country":[]}'::jsonb, 93),
  ('san-andres-colombia', '10S', 'San Andrés & Providencia, Colombia', 'Colombia', 'Coral islet, seven-colour sea', 'live', 'verified', 'tropicalBeach', 'Colombia''s Caribbean Coast', '{"tropical","liveaboard","romance","culture"}', '{"tropical"}', '{"essential","premier","luxury"}', null, null, '{"key_facts":["San Andrés — the ''Sea of Seven Colors'' — is Colombia''s Caribbean crown jewel, ringed by coral with 40+ mostly-shallow, high-visibility dive sites.","Providencia + Santa Catalina sit on the third-largest barrier reef in the world; Providencia rebuilt after Hurricane Iota (2020) and is open to tourism in 2026.","The Raizal are a Black Colombian Afro-Caribbean people; 20,000–30,000 speak San Andrés–Providencia Creole (Islander English) and most are trilingual.","Rondón — fish, conch, cassava, plantain and yam simmered in coconut milk — is the island''s signature dish (''run down'').","Mandatory Tourist Card (Tarjeta de Turismo) ~COP 153,000 (2026), bought at the airline counter before boarding the flight to ADZ."],"safety":{"emergency":"123","hospital":"Hospital Departamental Clarence Lynd Newball (San Andrés); hyperbaric/decompression chamber at Timothy Britton Hospital, San Andrés; serious cases referred off-island to mainland or US","book_enabled":true,"risk_codes":["C","T","U","K","N"],"risk_code_meanings":{"C":"Crime — violent crime (murder, assault, robbery), drugging (scopolamine/burundanga), extortion, express kidnapping occur throughout Colombia incl. cities (island crime skews to petty/beach theft + motorcycle snatch-and-grab)","T":"Terrorism — attacks possible with little/no warning; car bombs, grenades, IEDs, drones (mainland-weighted)","U":"Unrest — demonstrations can shut roads and turn violent","K":"Kidnapping or Hostage-Taking — kidnapping-for-ransom reported (mainland-weighted)","N":"Natural Disaster — mainland volcano/earthquake/landslide; archipelago hurricane/tropical-storm exposure (Hurricane Iota, Nov 2020)"},"named_danger":["Arauca","Cauca excl Popayán","Valle del Cauca excl Cali","Norte de Santander","Venezuela border ~10km"],"archipelago_in_named_danger":false,"island_crime_note":"island petty-crime (beach theft, motorcycle snatch-and-grab, scooter accidents) is lower and different from mainland violent crime; country-level advisory still renders in full at consent","air_access_verified":"ADZ (Gustavo Rojas Pinilla Intl) — direct international from Panama City (Copa, year-round) + domestic Colombian hubs; no nonstop US, but 1-stop via BOG/PTY (Avianca, Copa, LATAM). Providencia reached by ~20-min inter-island flight or catamaran.","remote_flag":true,"water":"bottled","vaccinations":"dengue/chikungunya/Zika present (peak rainy months); use insect protection; check CDC","scopolamine_caution":"''devil''s breath''/burundanga drugging — country-level; concentrates on mainland; never accept drinks/food from strangers","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/colombia","read":"2026-08-20T14:47:41Z","page_updated":"2026-08-18T15:51:11+01:00","source_country":"colombia","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"fcdo_zones":[{"name":"Arauca","lvl":4},{"name":"Norte de Santander","lvl":4},{"name":"Cauca","lvl":4,"except":["Popayan"],"note":"Parts of the department."},{"name":"Valle del Cauca","lvl":4,"except":["Cali"]},{"name":"Within ~10 km of the Venezuela border","lvl":4}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"CO","source":"UK FCDO, Mar 2026","_rule":"the FCDO restricted-area records for this country, verbatim. PRESENCE OF THIS BLOCK IS NOT A CLAIM THAT THIS DESTINATION SITS IN ANY OF THEM — membership is a coverage judgement and is set only in `zone_record`, by a human."}},"timing":{"peak":"Dec–Apr (dry); true peak January, then Feb–Mar (Colombians'' favorite domestic island)","inflection_curve_start":"early December","fire_date":"mid-to-late November (Dec–Jan peak); ~4–6 weeks before Semana Santa (late-Feb/early-Mar) for the Easter spike","event_peaks":[{"event":"Christmas–New Year","dates":"Dec 20–31","note":"maximum annual congestion; ADZ seats + rooms sell out"},{"event":"Semana Santa (Holy Week)","dates_2026":"Mar/Apr","note":"intense domestic coastal surge"}],"off_season_specials":"Sep–Nov (green season, lowest crowds, best deals); Jul–Aug secondary dry spell = best weather-to-cost; note higher dengue in rainy months"},"jewels":[{"name":"Sea of Seven Colors (Spratt Bight + lagoon)","si_tag":"tropical","tier":"essential","source":"https://colombia.travel/en/san-andres-island","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the seven-shade turquoise-to-cobalt water off the North End and the Aquarium/Haynes Cay flats; the island''s signature image","si":"tropical","blurb":"the seven-shade turquoise-to-cobalt water off the North End and the Aquarium/Haynes Cay flats; the island''s signature image","when":"Dec–Apr","commission":"hotel + boat-tour affiliate","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["tropical"],"shelf_fit":{"culture":"destination","liveaboard":"destination","romance":"destination","tropical":"primary"},"commission_lane":["affiliate","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Johnny Cay","si_tag":"tropical","tier":"essential","source":"https://www.lonelyplanet.com/colombia/san-andres-and-providencia/san-andres/attractions/johnny-cay-natural-regional-park/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"protected 4-ha coral islet ~1.5 km off San Andrés Town, coconut groves and the best white-sand beach around; colectivo boats from the town beach","si":"tropical","blurb":"protected 4-ha coral islet ~1.5 km off San Andrés Town, coconut groves and the best white-sand beach around; colectivo boats from the town beach","when":"Dec–Apr","commission":"GetYourGuide/Viator day-trip affiliate + park entry (non-comm)","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["tropical"],"shelf_fit":{"culture":"destination","liveaboard":"destination","romance":"destination","tropical":"primary"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"La Piscinita","si_tag":"tropical","tier":"essential","source":"https://www.tripadvisor.com/Attraction_Review-g3493965-d3228746-Reviews-La_Piscinita-San_Andres_San_Andres_Island_San_Andres_and_Providencia_Department.html","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"calm natural snorkel pool south of El Cove, dive board + water slide, reef fish, seafood restaurant + gear rental","si":"tropical","blurb":"calm natural snorkel pool south of El Cove, dive board + water slide, reef fish, seafood restaurant + gear rental","when":"Dec–Apr","commission":"day-tour affiliate + on-site entry (non-comm)","wells":["eat","activities","gear"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical"],"shelf_fit":{"culture":"destination","liveaboard":"destination","romance":"destination","tropical":"primary"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"West View (Mermaid Cave)","si_tag":"tropical","tier":"essential","source":"https://travelhapp.com/inspiration/things-to-do-in-san-andres-and-providencia","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Dec–Apr","commission":"day-tour affiliate + entry (non-comm)","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["tropical"],"shelf_fit":{"culture":"destination","liveaboard":"destination","romance":"destination","tropical":"primary"},"commission_lane":["affiliate"],"commissi